BEGIN;
UPDATE vilqa.fiber_config SET enabled=true;
DO $t$
DECLARE a bigint;b bigint;j jsonb;v jsonb;s jsonb;cnt integer;
BEGIN
 INSERT INTO vilqa.diary(user_id,date,time,item_name,item_type,weight,calories,protein,fats,carbs,draft_id,item_index) VALUES(180753266,'1900-01-01','12:00','ТЕСТ клетчатки яблоко','product',200,104,0.5,0.3,28,'fiber_test_transaction',0) RETURNING id INTO a;
 INSERT INTO vilqa.diary(user_id,date,time,item_name,item_type,weight,calories,protein,fats,carbs,draft_id,item_index) VALUES(180753266,'1900-01-01','12:00','ТЕСТ клетчатки курица','product',100,165,31,3.6,0,'fiber_test_transaction',1) RETURNING id INTO b;
 UPDATE vilqa.fiber_jobs SET ready_at=now()-interval '1 second' WHERE job_key='draft:fiber_test_transaction:1900-01-01';
 SELECT value INTO j FROM vilqa.fiber_claim('test') value;
 IF j IS NULL OR jsonb_array_length(j->'items')<>2 THEN RAISE EXCEPTION 'Queue did not group meal';END IF;
 IF EXISTS(SELECT 1 FROM vilqa.fiber_claim('second')) THEN RAISE EXCEPTION 'Duplicate job claim';END IF;
 SELECT jsonb_agg(jsonb_build_object('id',x->'id','signature',x->>'signature','fiber',CASE WHEN (x->>'id')::bigint=a THEN 4.8 ELSE 0 END)) INTO v FROM jsonb_array_elements(j->'items') x;
 SELECT value INTO s FROM vilqa.fiber_apply(j,v) value;
 IF (s->>'day_fiber')::numeric<>4.8 OR (s->>'day_unknown')::integer<>0 THEN RAISE EXCEPTION 'Incorrect day total: %',s;END IF;
 IF (SELECT count(*) FROM vilqa.diary WHERE draft_id='fiber_test_transaction')<>2 THEN RAISE EXCEPTION 'Created duplicate entries';END IF;
 SELECT count(*) INTO cnt FROM vilqa.fiber_reserve_notice(s);IF cnt<>1 THEN RAISE EXCEPTION 'Notice not reserved';END IF;
 SELECT count(*) INTO cnt FROM vilqa.fiber_reserve_notice(s);IF cnt<>0 THEN RAISE EXCEPTION 'Duplicate notice';END IF;
 UPDATE vilqa.diary SET weight=100 WHERE id=a;
 IF (SELECT fiber FROM vilqa.diary WHERE id=a) IS NOT NULL THEN RAISE EXCEPTION 'Stale fiber after edit';END IF;
 SELECT count(*) INTO cnt FROM vilqa.fiber_apply(j,v);IF cnt<>0 THEN RAISE EXCEPTION 'Applied stale revision';END IF;
 UPDATE vilqa.fiber_jobs SET ready_at=now()-interval '1 second' WHERE job_key='draft:fiber_test_transaction:1900-01-01';
 SELECT value INTO j FROM vilqa.fiber_claim('test2') value;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j->'items') x WHERE (x->>'id')::bigint=a AND (x->>'cached_per100')::numeric=2.4) THEN RAISE EXCEPTION 'Missing per100 cache';END IF;
 SELECT jsonb_agg(jsonb_build_object('id',x->'id','signature',x->>'signature','fiber',CASE WHEN (x->>'id')::bigint=a THEN 2.4 ELSE 0 END)) INTO v FROM jsonb_array_elements(j->'items') x;
 PERFORM vilqa.fiber_apply(j,v);
 UPDATE vilqa.diary SET deleted_at=now() WHERE id=a;
 UPDATE vilqa.fiber_jobs SET ready_at=now()-interval '1 second' WHERE job_key='draft:fiber_test_transaction:1900-01-01';
 SELECT value INTO j FROM vilqa.fiber_claim('test3') value;
 IF jsonb_array_length(j->'items')<>1 THEN RAISE EXCEPTION 'Deleted item still included';END IF;
 SELECT jsonb_agg(jsonb_build_object('id',x->'id','signature',x->>'signature','fiber',0)) INTO v FROM jsonb_array_elements(j->'items') x;
 SELECT value INTO s FROM vilqa.fiber_apply(j,v) value;
 IF (s->>'day_fiber')::numeric<>0 THEN RAISE EXCEPTION 'Deleted fiber still in totals';END IF;
 IF (vilqa.fiber_api(999999,'{"action":"day","user_id":180753266,"date":"1900-01-01"}') ->>'success')='true' THEN RAISE EXCEPTION 'Unauthorized API allowed';END IF;
 IF (vilqa.fiber_api(180753266,'{"action":"day","date":"1900-01-01"}')#>>'{totals,fiber}')::numeric<>0 THEN RAISE EXCEPTION 'Fiber missing from API';END IF;
 s:=vilqa.fiber_api(180753266,jsonb_build_object('action','edit','id',b,'version',1,'request_id','fiber_test_manual_01','patch',jsonb_build_object('item_name','ТЕСТ клетчатки курица','fiber',1.1,'weight',100,'calories',165,'protein',31,'fats',3.6,'carbs',0)));
 IF s->>'success'<>'true' OR (s#>>'{entry,fiber}')::numeric<>1.1 THEN RAISE EXCEPTION 'Manual fiber edit failed: %',s;END IF;
 UPDATE vilqa.diary SET date='1900-01-02' WHERE id=b;
 IF NOT EXISTS(SELECT 1 FROM vilqa.fiber_jobs WHERE job_key='draft:fiber_test_transaction:1900-01-01' AND status='pending') OR NOT EXISTS(SELECT 1 FROM vilqa.fiber_jobs WHERE job_key='draft:fiber_test_transaction:1900-01-02' AND status='pending') THEN RAISE EXCEPTION 'Date move did not queue both days';END IF;
 s:=vilqa.resolve_profile(180753266,'{}');
 v:=jsonb_build_object('name',s->>'name','age',(s->>'age')::numeric,'gender',s->>'gender','height',(s->>'height')::numeric,'weight',(s->>'weight')::numeric,'activity',(s->>'activity_level')::numeric,'goal',s->>'goal','daily_fiber',30);
 s:=vilqa.fiber_api(180753266,jsonb_build_object('action','profile_edit','version',s->'profile_version','request_id','fiber_test_profile_01','patch',v),jsonb_build_array(s));
 IF s->>'success'<>'true' OR (s#>>'{profile,daily_fiber}')::numeric<>30 THEN RAISE EXCEPTION 'Fiber target edit failed: %',s;END IF;
END $t$;
ROLLBACK;
SELECT 'PASS: grouped job, duplicate claims and notices, stale result rejected, proportional cache, delete totals, API auth, rollback' AS result;
